import{validateCampaign}from './campaign-core.mjs';
const $=id=>document.getElementById(id);let result=null,worker=null,busy=false;
function config(){return validateCampaign({seeds:+$('seeds').value,firstSeed:+$('firstSeed').value,steps:+$('steps').value,noise:+$('noise').value});}
function setBusy(b){busy=b;for(const el of $('study').querySelectorAll('input,select'))el.disabled=b;$('run').disabled=b;$('stop').hidden=!b;$('download').disabled=b||!result;}
function show(){ $('results').hidden=false;$('rows').replaceChildren();for(const r of result.runs){const tr=document.createElement('tr');for(const v of[r.seed,r.split,r.condition,r.metrics.forecastRMSE.toExponential(3),r.metrics.trueResidualRMS.toExponential(3)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('rows').append(tr);}let wins=0;for(const seed of result.protocol.confirmationSeeds){const e=k=>result.runs.find(r=>r.seed===seed&&r.condition===k).metrics.forecastRMSE;if(e('transfer')<e('correct')&&e('transfer')<e('scrambled'))wins++;}$('verdict').textContent=`Transferred hidden features beat both random and scrambled initialization on ${wins} of ${result.protocol.confirmationSeeds.length} confirmation seeds. This is descriptive same-task evidence, not a significance test or proof of a general rule.`;}
function run(){if(busy)return Promise.reject(Error('A study is already running.'));const c=config();result=null;$('results').hidden=true;setBusy(true);$('progress').value=0;$('status').textContent='Training matched model families…';worker=new Worker('./campaign-worker.js',{type:'module'});return new Promise((resolve,reject)=>{const fail=msg=>{worker.terminate();setBusy(false);$('status').textContent=msg;reject(Error(msg));};$('stop').onclick=()=>fail('Stopped. No partial study is presented as complete.');worker.onerror=()=>fail('Worker failed. Reload and try again.');worker.onmessage=({data})=>{if(data.error){fail(data.error);return;}if(data.done){result=data.result;worker.terminate();setBusy(false);$('progress').value=1;$('status').textContent=`Complete: ${result.runs.length} models. Download the study for Isomorph.`;show();resolve({models:result.runs.length,confirmationSeeds:result.protocol.confirmationSeeds});}else{const p=data.progress;$('progress').value=(p.completed+p.step/p.steps)/p.total;$('status').textContent=`Model ${p.completed+1}/${p.total} · seed ${p.seed} · ${p.condition} · step ${p.step}/${p.steps}`;}};worker.postMessage(c);});}
$('study').onsubmit=e=>{e.preventDefault();run().catch(e=>{$('status').textContent=e.message;});};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(result)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`transport-isomorph-seed-${result.config.firstSeed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};for(const el of $('study').querySelectorAll('input,select'))el.onchange=()=>{$('status').textContent=result?'Settings changed. Displayed results are still the completed study. Train again to apply.':`${+$('seeds').value*4} models will be trained, including the transfer controls.`;};
if(document.modelContext?.registerTool){const life=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'train_weight_study',title:'Train weight study',description:'Train controlled families and transfer controls; update the visible study.',inputSchema:{type:'object',properties:{seeds:{type:'integer',enum:[6,8,12]},steps:{type:'integer',enum:[1000,3000]},noise:{type:'number',enum:[0,.01]},firstSeed:{type:'integer',minimum:1,maximum:9999}},required:['seeds','steps','noise','firstSeed'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async c=>{validateCampaign(c);if(busy)throw Error('A study is already running.');for(const k of Object.keys(c))$(k).value=c[k];return run();}},{signal:life.signal})).catch(()=>{});window.addEventListener('pagehide',()=>{life.abort();worker?.terminate();},{once:true});}
